package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class LocalVariableDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BigDecimal amount = new BigDecimal("50000.00"); // Rajesh transfers rent

        // ─── BROKEN #1: would NOT compile ───
        // int fee;                       // local, no default
        // System.out.println(fee);       // ERROR: variable fee might not have been initialized

        // ─── BROKEN #2: would NOT compile (assigned on only one path) ───
        // int fee;
        // if (amount.compareTo(new BigDecimal("1000")) > 0) fee = 20;
        // System.out.println(fee);       // ERROR: on the else path fee is unassigned

        // ─── CORRECT #1: initialize at declaration ───
        int feeInitialized = 0; // safe default
        if (amount.compareTo(new BigDecimal("1000")) > 0) feeInitialized = 20;
        final int feeA = feeInitialized;
        log.info(() -> "Fee via declaration-init = " + feeA);

        // ─── CORRECT #2: assign on EVERY path (both branches) ───
        int feeEveryPath;
        if (amount.compareTo(new BigDecimal("1000")) > 0) {
            feeEveryPath = 20; // high-value transfer fee
        } else {
            feeEveryPath = 0;  // small transfer, no fee
        }
        final int feeB = feeEveryPath;
        log.info(() -> "Fee via every-path assignment = " + feeB);

        // ─── CORRECT #3: a throwing branch makes the surviving path definitely assigned ───
        int feeGuarded;
        if (amount.signum() <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        } else {
            feeGuarded = 20;
        }
        final int feeC = feeGuarded;
        log.info(() -> "Fee via guard-then-assign = " + feeC);

        log.info("All locals were definitely assigned before use → compiles and runs.");
    }
}
